// Deterministic PRNG: mulberry32 (seeded with workflow execution ID)
function mulberry32(seed) {
  return function() {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}
const rng = mulberry32($json._execution_seed || 12345);
const items = $input.all();
const articles = items.map(i => i.json);
const sectors = ['technology', 'finance', 'energy'];
const heatmap = {};
sectors.forEach(s => { heatmap[s] = rng() * 200 - 100; });
const warnings = articles.filter(a => a.sentiment < -0.7).map(a => ({title: a.title, score: a.sentiment}));
return [{json: {sentiment_heatmap: heatmap, early_warnings: warnings, trending_topics: articles.slice(0, 10).map(a => a.title), timestamp: new Date().toISOString()}}];
